window.xyIslandMotionSprites={"tree":"data:image/webp;base64,","swing": "data:image/webp;base64,", "fly": "data:image/webp;base64,", "land": "data:image/webp;base64,"};
/* 砚屿 V3: separate chibi sprites with three physical poses, not a zoomed flat storyboard. */
(()=>{
'use strict';
const scene=document.querySelector('#xyIslandHome'),world=scene?.querySelector('#xyIslandWorld');
if(!scene||!world||world.querySelector('.xy-island-film'))return;
const s=window.xyIslandMotionSprites;
if(!s||!s.swing||!s.fly||!s.land)return;
const film=document.createElement('div');film.className='xy-island-film';film.setAttribute('aria-hidden','true');
film.innerHTML='<div class="xy-film-islets"></div><div class="xy-film-tree"></div><div class="xy-film-mist first"></div><div class="xy-film-mist second"></div><div class="xy-film-leaves"></div>'+ 
'<div class="xy-film-swing"><img alt=""></div><div class="xy-film-trail"></div><div class="xy-film-fly"><img alt=""></div><div class="xy-film-land"><img alt=""></div>';
world.insertBefore(film,world.querySelector('.xy-island-foreground'));
for(const name of ['swing','fly','land'])film.querySelector('.xy-film-'+name+' img').src=s[name];
film.querySelector('.xy-film-tree').style.backgroundImage='url("'+s.tree+'")';
const bg=window.xyIslandPaintingData;
if(typeof bg==='string'&&bg.startsWith('data:image/'))film.style.setProperty('--xy-island-bg','url("'+bg+'")');
})();
